use split_decls_genesis :: ourprelude :: * ; use crate :: iter :: { FusedIterator , TrustedLen } ; use crate :: num :: NonZero ; #[doc = " Creates a new iterator that endlessly repeats a single element."] #[doc = ""] #[doc = " The `repeat()` function repeats a single value over and over again."] #[doc = ""] #[doc = " Infinite iterators like `repeat()` are often used with adapters like"] #[doc = " [`Iterator::take()`], in order to make them finite."] #[doc = ""] #[doc = " Use [`str::repeat()`] instead of this function if you just want to repeat"] #[doc = " a char/string `n`th times."] #[doc = ""] #[doc = " If the element type of the iterator you need does not implement `Clone`,"] #[doc = " or if you do not want to keep the repeated element in memory, you can"] #[doc = " instead use the [`repeat_with()`] function."] #[doc = ""] #[doc = " [`repeat_with()`]: crate::iter::repeat_with"] #[doc = " [`str::repeat()`]: ../../std/primitive.str.html#method.repeat"] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " Basic usage:"] #[doc = ""] #[doc = " ```"] #[doc = " use std::iter;"] #[doc = ""] #[doc = " // the number four 4ever:"] #[doc = " let mut fours = iter::repeat(4);"] #[doc = ""] #[doc = " assert_eq!(Some(4), fours.next());"] #[doc = " assert_eq!(Some(4), fours.next());"] #[doc = " assert_eq!(Some(4), fours.next());"] #[doc = " assert_eq!(Some(4), fours.next());"] #[doc = " assert_eq!(Some(4), fours.next());"] #[doc = ""] #[doc = " // yup, still four"] #[doc = " assert_eq!(Some(4), fours.next());"] #[doc = " ```"] #[doc = ""] #[doc = " Going finite with [`Iterator::take()`]:"] #[doc = ""] #[doc = " ```"] #[doc = " use std::iter;"] #[doc = ""] #[doc = " // that last example was too many fours. Let's only have four fours."] #[doc = " let mut four_fours = iter::repeat(4).take(4);"] #[doc = ""] #[doc = " assert_eq!(Some(4), four_fours.next());"] #[doc = " assert_eq!(Some(4), four_fours.next());"] #[doc = " assert_eq!(Some(4), four_fours.next());"] #[doc = " assert_eq!(Some(4), four_fours.next());"] #[doc = ""] #[doc = " // ... and now we're done"] #[doc = " assert_eq!(None, four_fours.next());"] #[doc = " ```"] #[inline] #[stable (feature = "rust1" , since = "1.0.0")] #[rustc_diagnostic_item = "iter_repeat"] pub fn repeat < T : Clone > (elt : T) -> Repeat < T > { Repeat { element : elt } } #[doc = " An iterator that repeats an element endlessly."] #[doc = ""] #[doc = " This `struct` is created by the [`repeat()`] function. See its documentation for more."] #[derive (Clone , Debug)] #[stable (feature = "rust1" , since = "1.0.0")] pub struct Repeat < A > { element : A , } #[stable (feature = "rust1" , since = "1.0.0")] impl < A : Clone > Iterator for Repeat < A > { type Item = A ; #[inline] fn next (& mut self) -> Option < A > { Some (self . element . clone ()) } #[inline] fn size_hint (& self) -> (usize , Option < usize >) { (usize :: MAX , None) } #[inline] fn advance_by (& mut self , n : usize) -> Result < () , NonZero < usize > > { let _ = n ; Ok (()) } #[inline] fn nth (& mut self , n : usize) -> Option < A > { let _ = n ; Some (self . element . clone ()) } fn last (self) -> Option < A > { loop { } } fn count (self) -> usize { loop { } } } #[stable (feature = "rust1" , since = "1.0.0")] impl < A : Clone > DoubleEndedIterator for Repeat < A > { #[inline] fn next_back (& mut self) -> Option < A > { Some (self . element . clone ()) } #[inline] fn advance_back_by (& mut self , n : usize) -> Result < () , NonZero < usize > > { let _ = n ; Ok (()) } #[inline] fn nth_back (& mut self , n : usize) -> Option < A > { let _ = n ; Some (self . element . clone ()) } } #[stable (feature = "fused" , since = "1.26.0")] impl < A : Clone > FusedIterator for Repeat < A > { } #[unstable (feature = "trusted_len" , issue = "37572")] unsafe impl < A : Clone > TrustedLen for Repeat < A > { }